"""Small formatting helpers."""


def fmt_ms(x):
    """Format a millisecond count as a string like '123ms'.

    Raises ValueError if x is negative.
    """
    if x < 0:
        raise ValueError(f"negative millisecond value: {x}")
    return f"{x}ms"
